from __future__ import annotations

from fastapi.responses import HTMLResponse


def operator_page() -> HTMLResponse:
    return HTMLResponse(
        r'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Nmap Terrain Analyzer · Nmap Scans</title>
  <style>
    :root{color-scheme:dark;--bg:#08141d;--panel:#0f1d27;--panel2:#152b35;--line:#294553;--text:#e7eef8;--muted:#9eb0b8;--accent:#57d6bf;--blue:#73bfff;--good:#61d095;--warn:#f4c95d;--bad:#ff7b7b}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#08141d,#10242e);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}header,main{max-width:1180px;margin:auto}header{padding:26px 0 20px;border-bottom:1px solid var(--line)}h1{margin:0 0 4px;font-size:29px}h2{margin:0 0 8px;font-size:19px}h3{margin:0 0 8px;font-size:15px}.sub,.hint,.meta{color:var(--muted)}.sub{margin:0}.eyebrow{color:var(--accent);font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:11px}.nav{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.nav a{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:9px 13px;text-decoration:none;font-weight:700}.nav a.active{background:var(--accent);border-color:var(--accent);color:#07171b}main{padding:24px 0 60px}.panel{background:rgba(15,29,39,.95);border:1px solid var(--line);border-radius:13px;padding:20px;box-shadow:0 10px 35px #0003;margin-bottom:18px}.builder{border-color:#3a756d}.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:13px}.span-12{grid-column:span 12}.span-6{grid-column:span 6}.span-4{grid-column:span 4}.span-3{grid-column:span 3}.two-column{display:grid;grid-template-columns:minmax(0,1fr) minmax(340px,.72fr);gap:18px;align-items:start}label{display:block;color:#bed0da;font-size:12px;font-weight:700;margin:4px 0 5px}input,select,textarea{width:100%;background:#0b1520;color:var(--text);border:1px solid #365268;border-radius:8px;padding:10px 11px;font:inherit}textarea{min-height:90px;resize:vertical}input:focus,select:focus,textarea:focus{outline:2px solid #57d6bf44;border-color:var(--accent)}.check-row{display:flex;gap:18px;flex-wrap:wrap;align-items:center;padding-top:8px}.check{display:flex;gap:7px;align-items:center}.check input{width:auto}.actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin-top:17px}button{border:1px solid #3b6f91;background:#174665;color:#fff;border-radius:7px;padding:10px 14px;font:inherit;font-weight:750;cursor:pointer}button:hover{background:#1d587d}button.primary{background:var(--accent);border-color:var(--accent);color:#07171b}button.secondary{background:transparent;border-color:#49617d}button.danger{background:#612f3a;border-color:#a95561}button:disabled{opacity:.5;cursor:not-allowed}.status{min-height:24px;margin-top:12px;color:var(--muted)}.status.good{color:var(--good)}.status.warn{color:var(--warn)}.status.bad{color:var(--bad)}.profile-note{padding:10px 12px;background:#0a1720;border:1px solid var(--line);border-radius:8px;margin-top:10px}.pill{display:inline-flex;padding:4px 9px;border-radius:99px;background:#31425a;font-size:11px;font-weight:800;text-transform:uppercase}.pill.completed{background:#1e5e46;color:#bff4d6}.pill.running,.pill.queued{background:#1c5270;color:#bfe9ff}.pill.failed,.pill.cancelled,.pill.timed_out{background:#66313b;color:#ffd0d0}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:13px 0}.summary div{background:#0a1720;border:1px solid var(--line);border-radius:8px;padding:10px}.summary strong{display:block;color:var(--blue);font-size:18px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:980px}th,td{text-align:left;vertical-align:top;padding:9px 7px;border-bottom:1px solid #263f49}th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.05em}td{font-size:12px}code,pre{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}code{color:#9edcff}pre{white-space:pre-wrap;overflow:auto;max-height:240px;background:#09111b;border:1px solid var(--line);border-radius:8px;padding:11px;color:#cce7f5}.artifacts{display:flex;flex-wrap:wrap;gap:7px}.artifacts a{color:#8be1d0;border:1px solid #315264;border-radius:6px;padding:5px 8px;text-decoration:none}.hidden{display:none!important}.footer{color:var(--muted);font-size:12px;margin-top:16px}.confirm-panel{margin-top:14px;padding:13px;border:1px solid #a95561;border-radius:9px;background:#2b1a22}@media(max-width:1200px){header,main{padding-left:4vw;padding-right:4vw}}@media(max-width:850px){.two-column{grid-template-columns:1fr}.span-6,.span-4,.span-3{grid-column:span 12}.summary{grid-template-columns:1fr 1fr}}
  </style>
</head>
<body>
  <header>
    <div class="eyebrow">Unified scan workspace</div>
    <h1>Nmap Scans</h1>
    <p class="sub">Build once, then save the profile, run it now, or generate a portable scan package.</p>
    <nav class="nav" aria-label="Primary"><a class="active" href="/scans" aria-current="page">Nmap Scans</a><a href="/analysis">Analyze Results</a><a href="/device-config">Device Configurations</a><a href="/network-map">Network Map</a></nav>
  </header>
  <main>
    <section class="panel builder">
      <h2>Build scan</h2>
      <p class="hint">All Nmap commands generated here include <code>-n</code>. Saved schedules will remain pinned to the selected profile version.</p>
      <div class="grid">
        <div class="span-4"><label for="scanName">Scan name</label><input id="scanName" value="Terrain_Baseline" maxlength="100"></div>
        <div class="span-4"><label for="profileSelect">Saved profile</label><select id="profileSelect"><option value="">Loading profiles…</option></select></div>
        <div class="span-4"><label for="profileName">Profile name for save / clone</label><input id="profileName" value="Mission Profile" maxlength="100"></div>
        <div class="span-6"><label for="targets">Targets</label><textarea id="targets" placeholder="172.22.10.0/24"></textarea></div>
        <div class="span-6"><label for="noStrike">No-strike addresses (optional)</label><textarea id="noStrike" placeholder="172.22.10.1&#10;172.22.10.10/32"></textarea></div>
        <div class="span-4"><label for="protocol">Protocol</label><select id="protocol"><option value="tcp">TCP</option><option value="udp">UDP</option><option value="tcp_udp">TCP + UDP</option></select></div>
        <div class="span-4 tcp-option"><label for="tcpScope">TCP port scope</label><select id="tcpScope"><option value="top_1000">Top 1,000</option><option value="common">Common</option><option value="ics">ICS / OT</option><option value="custom">Custom</option><option value="all">All TCP ports</option></select></div>
        <div class="span-4 udp-option hidden"><label for="udpScope">UDP port scope</label><select id="udpScope"><option value="top_100">Top 100</option><option value="common">Common</option><option value="ics">ICS / OT</option><option value="custom">Custom</option><option value="all">All UDP ports</option></select></div>
        <div class="span-6 tcp-custom hidden"><label for="tcpPorts">Custom TCP ports</label><input id="tcpPorts" placeholder="22,80,443,8000-8100"></div>
        <div class="span-6 udp-custom hidden"><label for="udpPorts">Custom UDP ports</label><input id="udpPorts" placeholder="53,123,161,47808"></div>
        <div class="span-3"><label for="timing">Timing</label><select id="timing"><option value="conservative">Conservative · T2</option><option value="normal">Normal · T3</option><option value="fast" selected>Fast · T4</option></select></div>
        <div class="span-3"><label for="interface">Analyzer interface</label><select id="interface"><option value="">Loading…</option></select></div>
        <div class="span-3"><label for="timeout">Run timeout (seconds)</label><input id="timeout" type="number" min="10" max="3600" value="900"></div>
        <div class="span-3"><label for="chunkSize">Package chunk size</label><input id="chunkSize" type="number" min="1" max="4096" value="256"></div>
        <div class="span-6"><label for="operator">Creator / operator</label><input id="operator" placeholder="Analyst name"></div>
        <div class="span-6"><label for="origin">Originating host</label><input id="origin" placeholder="kali-blue"></div>
        <div class="span-12"><label for="reason">Reason / authorization note</label><input id="reason" placeholder="Authorized terrain characterization"></div>
        <div class="span-12 check-row"><label class="check"><input id="serviceDetection" type="checkbox" checked>Service/version detection</label><label class="check"><input id="osDetection" type="checkbox" checked>OS detection</label></div>
      </div>
      <div id="profileNote" class="profile-note meta">Select a saved profile or customize these settings.</div>
      <div class="actions">
        <button id="runNow" class="primary" type="button">Run now</button>
        <button id="generatePackage" type="button">Generate package</button>
        <button id="preview" class="secondary" type="button">Preview command</button>
        <button id="saveProfile" class="secondary" type="button">Save as profile</button>
        <button id="saveVersion" class="secondary" type="button" disabled>Save new version</button>
        <button id="cloneProfile" class="secondary" type="button" disabled>Clone profile</button>
      </div>
      <div id="builderStatus" class="status" role="status" aria-live="polite"></div>
      <details><summary>Generated command preview</summary><pre id="commandPreview">Choose settings, then select Preview command.</pre></details>
    </section>

    <div class="two-column">
      <section class="panel">
        <h2>Current run</h2>
        <div id="currentEmpty" class="meta">No scan selected. Run a scan or open one from history.</div>
        <div id="current" class="hidden">
          <div><span id="currentStatus" class="pill">—</span> <strong id="currentName"></strong></div>
          <div class="summary"><div><strong id="currentHosts">—</strong>hosts</div><div><strong id="currentProtocols">—</strong>protocols</div><div><strong id="currentProfile">—</strong>profile</div><div><strong id="currentMethod">—</strong>method</div></div>
          <p class="meta" id="currentMetadata"></p>
          <details open><summary>Command accountability</summary><pre id="currentCommand"></pre></details>
          <div id="currentArtifacts" class="artifacts"></div>
          <div class="actions"><button id="analyzeCurrent" class="secondary" disabled>Open &amp; analyze</button><button id="cancel" class="danger" disabled>Cancel active scan</button></div>
        </div>
      </section>
      <section class="panel">
        <h2>Profile behavior</h2>
        <p>Built-in profiles are protected templates. Clone one to customize it.</p>
        <p>Saving a new version preserves older versions. Future schedule definitions retain their exact profile version until explicitly changed.</p>
        <p class="hint">Actual recurring execution remains in the later scheduling phase; the version-pinned storage contract is ready now.</p>
      </section>
    </div>

    <section class="panel">
      <div class="actions" style="justify-content:space-between;margin-top:0"><div><h2>Scan history</h2><p class="hint">Coverage, ownership, execution method, and profile version remain attached to every run.</p></div><div><button id="refresh" class="secondary">Refresh</button><button id="deleteAll" class="danger">Clear stored scan data</button></div></div>
      <div id="history" class="meta">Loading…</div>
      <div id="deleteConfirm" class="confirm-panel hidden"><strong id="deleteTitle">Confirm deletion</strong><p id="deletePrompt"></p><p>Type this one-time confirmation string exactly: <code id="deleteChallenge"></code></p><input id="deleteInput" autocomplete="off" spellcheck="false"><div class="actions"><button id="confirmDelete" class="danger">Confirm deletion</button><button id="cancelDelete" class="secondary">Cancel</button></div></div>
    </section>
    <div class="footer">Nmap execution requires the analyzer VM and always records tcpdump accountability evidence. Portable packages can be run from an authorized scanning host.</div>
  </main>
<script>
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines=id=>$(id).value.split(/[\r\n,]+/).map(value=>value.trim()).filter(Boolean);
let profiles=[],selectedProfile=null,profileDirty=false,currentId=null,pollTimer=null,pendingDelete=null;
function status(message,kind=''){const node=$('builderStatus');node.textContent=message;node.className='status '+kind}
function settings(){return{protocol:$('protocol').value,tcp_scope:$('tcpScope').value,tcp_ports:$('tcpPorts').value.trim(),udp_scope:$('udpScope').value,udp_ports:$('udpPorts').value.trim(),service_detection:$('serviceDetection').checked,os_detection:$('osDetection').checked,timing:$('timing').value}}
function showOptions(){const protocol=$('protocol').value;document.querySelectorAll('.tcp-option').forEach(n=>n.classList.toggle('hidden',protocol==='udp'));document.querySelectorAll('.udp-option').forEach(n=>n.classList.toggle('hidden',protocol==='tcp'));document.querySelectorAll('.tcp-custom').forEach(n=>n.classList.toggle('hidden',protocol==='udp'||$('tcpScope').value!=='custom'));document.querySelectorAll('.udp-custom').forEach(n=>n.classList.toggle('hidden',protocol==='tcp'||$('udpScope').value!=='custom'))}
function coverageLabel(run){const coverage=run.coverage||{},protocols=(coverage.protocols||[]).join(' + ')||'—',parts=[];if(coverage.tcp_scope)parts.push(`TCP ${coverage.tcp_scope.replaceAll('_',' ')}`);if(coverage.udp_scope)parts.push(`UDP ${coverage.udp_scope.replaceAll('_',' ')}`);return `${protocols} · ${parts.join(' / ')||'scope unavailable'}`}
function setDirty(){if(!selectedProfile)return;profileDirty=true;$('profileNote').textContent=`Custom changes based on ${selectedProfile.name} v${selectedProfile.version}; run/generate will use this unsaved snapshot.`;updateProfileButtons()}
function applyProfile(profile){selectedProfile=profile;profileDirty=false;const s=profile.settings||{};$('protocol').value=s.protocol||'tcp';$('tcpScope').value=s.tcp_scope||'top_1000';$('tcpPorts').value=s.tcp_ports||'';$('udpScope').value=s.udp_scope||'top_100';$('udpPorts').value=s.udp_ports||'';$('serviceDetection').checked=s.service_detection!==false;$('osDetection').checked=s.os_detection!==false;$('timing').value=s.timing||'fast';$('profileName').value=profile.name;$('profileNote').textContent=`${profile.name} v${profile.version} · ${profile.description||'Saved profile'}${profile.built_in?' · protected built-in':''}`;showOptions();updateProfileButtons()}
function updateProfileButtons(){$('saveVersion').disabled=!selectedProfile||selectedProfile.built_in;$('cloneProfile').disabled=!selectedProfile}
function profilePayload(){if(selectedProfile&&!profileDirty)return{profile:selectedProfile.name,profile_id:selectedProfile.profile_id,profile_version:selectedProfile.version};return{profile:'Custom',scan_options:settings()}}
function commonPayload(){return{name:$('scanName').value.trim(),operator:$('operator').value.trim(),created_by:$('operator').value.trim(),reason:$('reason').value.trim(),originating_host:$('origin').value.trim()||location.hostname,interface:$('interface').value,targets:lines('targets'),no_strike:lines('noStrike'),...profilePayload()}}
function validateCommon(requireRun=false){const p=commonPayload();if(!p.name||!p.operator||!p.reason||!p.targets.length)throw new Error('Scan name, creator/operator, reason, and at least one target are required.');if(requireRun&&!p.interface)throw new Error('Choose an analyzer interface before running.');return p}
async function loadProfiles(selectId=null){const r=await fetch('/api/scan-profiles');const data=await r.json();if(!r.ok)throw new Error(data.detail||'Profiles could not be loaded');profiles=data||[];$('profileSelect').innerHTML=profiles.map(p=>`<option value="${esc(p.profile_id)}:${p.version}">${esc(p.name)} · v${p.version}${p.built_in?' · built-in':''}</option>`).join('');const chosen=profiles.find(p=>`${p.profile_id}:${p.version}`===selectId)||profiles[0];if(chosen){$('profileSelect').value=`${chosen.profile_id}:${chosen.version}`;applyProfile(chosen)}}
async function loadInterfaces(){try{const r=await fetch('/api/scan-runs/interfaces'),data=await r.json();$('interface').innerHTML=(data.interfaces||[]).map(i=>`<option value="${esc(i)}">${esc(i)}</option>`).join('')||'<option value="">No interfaces found</option>'}catch(error){status('Interfaces unavailable: '+error.message,'warn')}}
async function preview(){try{const p=validateCommon(false),body={name:p.name,created_by:p.created_by,profile:p.profile,profile_id:p.profile_id,profile_version:p.profile_version,scan_options:p.scan_options,terrain:[{name:'Target_scope',targets:p.targets}],no_strike_mode:p.no_strike.length?'entered':'none',no_strike:p.no_strike,chunk_size:Number($('chunkSize').value)};status('Generating validated command preview…');const r=await fetch('/api/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Preview failed');$('commandPreview').textContent=data.copy_text;status(`Validated ${data.profile} v${data.profile_version}; mandatory -n is present.`,'good')}catch(error){status(error.message,'bad')}}
async function generatePackage(){try{const p=validateCommon(false),body={name:p.name,created_by:p.created_by,profile:p.profile,profile_id:p.profile_id,profile_version:p.profile_version,scan_options:p.scan_options,terrain:[{name:'Target_scope',targets:p.targets}],no_strike_mode:p.no_strike.length?'entered':'none',no_strike:p.no_strike,chunk_size:Number($('chunkSize').value)};status('Building and certifying the portable package…');const r=await fetch('/api/packages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok){const data=await r.json();throw new Error(data.detail||'Package generation failed')}const blob=await r.blob(),link=document.createElement('a'),disposition=r.headers.get('content-disposition')||'';link.href=URL.createObjectURL(blob);link.download=(disposition.match(/filename="([^"]+)"/)||[])[1]||'nmap-scan-package.zip';link.click();URL.revokeObjectURL(link.href);status(`Package generated: ${link.download}`,'good')}catch(error){status(error.message,'bad')}}
async function runNow(){try{const payload={...validateCommon(true),capture:true,timeout_seconds:Number($('timeout').value)};status('Submitting scan with accountability capture…');$('runNow').disabled=true;const r=await fetch('/api/scan-runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Scan could not start');setCurrent(data);status(`${data.display_name} queued.`,'good');clearTimeout(pollTimer);poll();await loadHistory()}catch(error){status(error.message,'bad')}finally{$('runNow').disabled=false}}
async function saveProfile(){try{const body={name:$('profileName').value.trim(),description:`Saved from scan builder for ${$('scanName').value.trim()}`,created_by:$('operator').value.trim(),settings:settings()};if(!body.name||!body.created_by)throw new Error('Profile name and creator/operator are required.');const r=await fetch('/api/scan-profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Profile could not be saved');await loadProfiles(`${data.profile_id}:${data.version}`);status(`Saved ${data.name} v${data.version}.`,'good')}catch(error){status(error.message,'bad')}}
async function saveVersion(){try{if(!selectedProfile||selectedProfile.built_in)throw new Error('Clone a built-in profile before editing it.');const body={description:`Updated from scan builder for ${$('scanName').value.trim()}`,created_by:$('operator').value.trim(),settings:settings()};if(!body.created_by)throw new Error('Creator/operator is required.');const r=await fetch(`/api/scan-profiles/${encodeURIComponent(selectedProfile.profile_id)}/versions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Version could not be saved');await loadProfiles(`${data.profile_id}:${data.version}`);status(`Saved ${data.name} v${data.version}; earlier versions remain unchanged.`,'good')}catch(error){status(error.message,'bad')}}
async function cloneProfile(){try{if(!selectedProfile)throw new Error('Select a profile to clone.');let name=$('profileName').value.trim();if(!name||name===selectedProfile.name)name=`${selectedProfile.name} Copy`;const body={name,description:`Cloned from ${selectedProfile.name} v${selectedProfile.version}`,created_by:$('operator').value.trim(),source_version:selectedProfile.version};if(!body.created_by)throw new Error('Creator/operator is required.');const r=await fetch(`/api/scan-profiles/${encodeURIComponent(selectedProfile.profile_id)}/clone`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Profile could not be cloned');await loadProfiles(`${data.profile_id}:${data.version}`);status(`Cloned as ${data.name} v1.`,'good')}catch(error){status(error.message,'bad')}}
function setCurrent(run){currentId=run.run_id;$('currentEmpty').classList.add('hidden');$('current').classList.remove('hidden');const state=String(run.status||'unknown');$('currentStatus').textContent=state;$('currentStatus').className=`pill ${state}`;$('currentName').textContent=run.display_name||run.name||run.run_id;$('currentHosts').textContent=run.host_count??'—';$('currentProtocols').textContent=(run.coverage?.protocols||[]).join('+')||'—';$('currentProfile').textContent=`${run.profile||'—'} v${run.profile_version||'—'}`;$('currentMethod').textContent=run.execution_method||'—';$('currentMetadata').textContent=`Created by ${run.created_by||run.operator||'—'} · Executed by ${run.executed_by||'—'} · ${(run.targets||[]).join(', ')} · ${coverageLabel(run)}`;$('currentCommand').textContent=[run.exact_command,run.capture_requested?`Capture: ${run.exact_capture_command||''}`:'Capture: not requested'].join('\n');const artifacts=run.artifacts||[];$('currentArtifacts').innerHTML=artifacts.length?artifacts.map(a=>`<a href="${esc(a.download_url)}" download>${esc(a.name)}</a>`).join(''):'<span class="meta">Artifacts will appear when the run finishes.</span>';$('cancel').disabled=!['queued','running'].includes(state);$('analyzeCurrent').disabled=!(state==='completed'&&artifacts.some(a=>a.name==='xml'))}
async function selectRun(id){try{const r=await fetch(`/api/scan-runs/${encodeURIComponent(id)}`),data=await r.json();if(!r.ok)throw new Error(data.detail||'Run not found');setCurrent(data);window.scrollTo({top:document.querySelector('.two-column').offsetTop-20,behavior:'smooth'})}catch(error){status(error.message,'bad')}}
async function poll(){if(!currentId)return;try{const r=await fetch(`/api/scan-runs/${encodeURIComponent(currentId)}`),run=await r.json();if(!r.ok)throw new Error(run.detail||'Status request failed');setCurrent(run);if(['queued','running'].includes(run.status))pollTimer=setTimeout(poll,1500);else{await loadHistory();status(`Run ${run.status}.`,'good')}}catch(error){status(error.message,'bad')}}
async function loadHistory(){try{const r=await fetch('/api/scan-runs?limit=50'),data=await r.json();if(!r.ok)throw new Error(data.detail||'History request failed');if(!data.length){$('history').innerHTML='<div class="meta">No scan runs yet.</div>';return}$('history').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Status / name</th><th>When</th><th>Ownership</th><th>Coverage</th><th>Profile</th><th>Results</th></tr></thead><tbody>${data.map(run=>`<tr><td><span class="pill ${esc(run.status)}">${esc(run.status)}</span><br><strong>${esc(run.display_name||run.name||run.run_id)}</strong><br><code>${esc(run.run_id.slice(0,12))}</code></td><td>${esc(run.created_at||'—')}<br><span class="meta">${esc(run.completed_at?'completed '+run.completed_at:'')}</span></td><td>Created: ${esc(run.created_by||run.operator||'—')}<br>Scheduled: ${esc(run.scheduled_by||'—')}<br>Executed: ${esc(run.executed_by||'—')} · ${esc(run.execution_method||'manual')}</td><td>${esc((run.targets||[]).join(', ')||'—')}<br>${esc(coverageLabel(run))}<br><span class="meta">via ${esc(run.interface||'—')} · ${Number(run.host_count??0)} hosts</span></td><td>${esc(run.profile||'—')} v${esc(run.profile_version||'—')}<br><span class="meta">${run.capture_requested?'PCAP captured':''}</span></td><td><button class="secondary" data-open="${esc(run.run_id)}">Open</button> ${run.status==='completed'?`<button data-analyze="${esc(run.run_id)}">Open &amp; analyze</button>`:''} <button class="danger" data-delete="${esc(run.run_id)}">Delete</button><div class="artifacts">${(run.artifacts||[]).map(a=>`<a href="${esc(a.download_url)}" download>${esc(a.name)}</a>`).join('')}</div></td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>selectRun(b.dataset.open));document.querySelectorAll('[data-analyze]').forEach(b=>b.onclick=()=>location.href=`/analysis?run=${encodeURIComponent(b.dataset.analyze)}`);document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>beginDelete('scan',b.dataset.delete))}catch(error){$('history').innerHTML=`<div class="status bad">${esc(error.message)}</div>`}}
async function beginDelete(scope,runId=null){try{const r=await fetch(`/api/scan-runs/delete-challenge${runId?`?run_id=${encodeURIComponent(runId)}`:''}`,{method:'POST'}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Could not prepare deletion');pendingDelete={scope,runId};$('deleteTitle').textContent=scope==='all'?'Clear all stored scan data':'Delete this scan run';$('deletePrompt').textContent=scope==='all'?'This removes automated runs and imported Nmap results. Device configurations are preserved.':'This removes this run and all retained evidence.';$('deleteChallenge').textContent=data.challenge;$('deleteInput').value='';$('deleteConfirm').classList.remove('hidden')}catch(error){status(error.message,'bad')}}
async function confirmDelete(){if(!pendingDelete)return;try{const url=pendingDelete.scope==='all'?'/api/scan-runs/delete-all':`/api/scan-runs/${encodeURIComponent(pendingDelete.runId)}/delete`,r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation:$('deleteInput').value.trim()})}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Deletion failed');pendingDelete=null;$('deleteConfirm').classList.add('hidden');await loadHistory();status('Stored scan data deleted.','good')}catch(error){status(error.message,'bad')}}
$('profileSelect').onchange=()=>{const [id,version]=$('profileSelect').value.split(':');const profile=profiles.find(p=>p.profile_id===id&&String(p.version)===version);if(profile)applyProfile(profile)};
['protocol','tcpScope','udpScope','tcpPorts','udpPorts','serviceDetection','osDetection','timing'].forEach(id=>$(id).addEventListener('change',()=>{showOptions();setDirty()}));
$('preview').onclick=preview;$('generatePackage').onclick=generatePackage;$('runNow').onclick=runNow;$('saveProfile').onclick=saveProfile;$('saveVersion').onclick=saveVersion;$('cloneProfile').onclick=cloneProfile;$('refresh').onclick=loadHistory;$('cancel').onclick=async()=>{if(!currentId)return;const r=await fetch(`/api/scan-runs/${encodeURIComponent(currentId)}/cancel`,{method:'POST'});if(r.ok)poll()};$('analyzeCurrent').onclick=()=>{if(currentId)location.href=`/analysis?run=${encodeURIComponent(currentId)}`};$('deleteAll').onclick=()=>beginDelete('all');$('confirmDelete').onclick=confirmDelete;$('cancelDelete').onclick=()=>{pendingDelete=null;$('deleteConfirm').classList.add('hidden')};
$('origin').value=location.hostname;Promise.all([loadProfiles(),loadInterfaces(),loadHistory()]).catch(error=>status(error.message,'bad'));
</script>
</body></html>'''
    )
